param([string]$BaseUrl='http://localhost:14200',[ValidateRange(30,300)][int]$MaxWaitSeconds=120)
$ErrorActionPreference='Stop';$root=(Resolve-Path(Join-Path $PSScriptRoot '../..')).Path
$envNames=@('SCHEDULING_RABBITMQ_ENABLED','SCHEDULING_ROCKETMQ_ENABLED','SCHEDULING_RABBITMQ_PUBLISH_FIXED_DELAY','SCHEDULING_ROCKETMQ_PUBLISH_FIXED_DELAY');$saved=@{};foreach($n in $envNames){$saved[$n]=[Environment]::GetEnvironmentVariable($n)}
function Compose([string[]]$Arguments){& docker compose --project-directory $root @Arguments;if($LASTEXITCODE-ne0){throw "Compose failed: $($Arguments-join' ')"}}
function Sql([string]$Statement){$v=& docker compose --project-directory $root exec -T commerce-db mysql -ucommerceflow -pcommerceflow-password -Nse $Statement commerceflow 2>$null;if($LASTEXITCODE-ne0){throw 'SQL failed'};return($v-join"`n").Trim()}
function Session([string]$Email){$s=[Microsoft.PowerShell.Commands.WebRequestSession]::new();$c=Invoke-RestMethod "$BaseUrl/api/auth/csrf" -WebSession $s;$h=@{};$h[$c.headerName]=$c.token;Invoke-RestMethod "$BaseUrl/api/auth/login" -Method Post -WebSession $s -Headers $h -ContentType application/json -Body (@{email=$Email;password='demo-password';rememberMe=$false}|ConvertTo-Json -Compress)|Out-Null;return @{Session=$s;Headers=$h}}
function Wait-Web{for($i=0;$i-lt60;$i++){try{Invoke-RestMethod "$BaseUrl/api/products"|Out-Null;return}catch{};Start-Sleep 1};throw 'Storefront did not become ready'}
function Set-Policy($Admin,[string]$Type,[string]$Trigger,$Original=$null){if($Original){$body=@{enabled=[bool]$Original.enabled;primaryTrigger=[string]$Original.primaryTrigger;reconciliationEnabled=[bool]$Original.reconciliationEnabled;gracePeriodSeconds=[int]$Original.gracePeriodSeconds;claimLeaseSeconds=[int]$Original.claimLeaseSeconds;maxAttempts=[int]$Original.maxAttempts;retryDelaySeconds=[int]$Original.retryDelaySeconds}|ConvertTo-Json -Compress}else{$body=@{enabled=$true;primaryTrigger=$Trigger;reconciliationEnabled=$false;gracePeriodSeconds=0;claimLeaseSeconds=30;maxAttempts=8;retryDelaySeconds=1}|ConvertTo-Json -Compress};Invoke-RestMethod "$BaseUrl/api/admin/scheduling/policies/$Type" -Method Put -WebSession $Admin.Session -Headers $Admin.Headers -ContentType application/json -Body $body}
function Wait-Sql([string]$Query,[scriptblock]$Accept,[string]$Label){$end=(Get-Date).AddSeconds($MaxWaitSeconds);do{$value=Sql $Query;if(&$Accept $value){return $value};Start-Sleep -Milliseconds 500}while((Get-Date)-lt$end);throw "$Label timed out (last=$value)"}
function Broker([string]$Trigger,[string]$Action){$service=if($Trigger-eq'RABBITMQ'){'rabbitmq-broker'}else{'rocketmq-broker'};$profile=if($Trigger-eq'RABBITMQ'){'rabbitmq'}else{'rocketmq'};if($Action-eq'stop'){Compose @('--profile',$profile,'stop',$service)}else{Compose @('--profile',$profile,'up','-d','--wait',$service)}}
function New-DeliveredOrder{& "$PSScriptRoot/verify-logistics.ps1" -BaseUrl $BaseUrl|Out-Host;if(-not$?){throw 'Could not create delivered shipment'};$id=Sql "SELECT o.id FROM shop_orders o JOIN shipment_records s ON s.order_id=o.id JOIN app_users u ON u.id=o.customer_id WHERE u.email='demo@example.com' AND o.status='SHIPPED' AND s.status='DELIVERED' ORDER BY o.created_at DESC,o.id DESC LIMIT 1";if(-not$id){throw 'Delivered order not found'};return [long]$id}
function Assert-PublishFailure([long]$TaskId,[string]$Type){Wait-Sql "SELECT trigger_publish_attempts FROM scheduled_tasks WHERE id=$TaskId" {param($v) [int]$v -ge 1} "$Type publish failure"|Out-Null;$error=Sql "SELECT COALESCE(trigger_last_error,'') FROM scheduled_tasks WHERE id=$TaskId";if([string]::IsNullOrWhiteSpace($error)){throw "$Type did not record broker publish failure"}}
function Verify-Task([long]$TaskId,[string]$Trigger,[string]$ExpectedOrderStatus,[long]$OrderId){Wait-Sql "SELECT status FROM shop_orders WHERE id=$OrderId" {param($v)$v-eq$ExpectedOrderStatus} "$Trigger order $ExpectedOrderStatus"|Out-Null;$audit=Sql "SELECT CONCAT(status,':',last_trigger_source,':',primary_trigger_snapshot) FROM scheduled_tasks WHERE id=$TaskId";if($audit-ne"SUCCEEDED:$Trigger`:$Trigger"){throw "Unexpected $Trigger task audit: $audit"};$count=[int](Sql "SELECT COUNT(*) FROM scheduled_task_events WHERE task_id=$TaskId AND event_type='TASK_SUCCEEDED'");if($count-ne1){throw "$Trigger task succeeded $count times"}}

$admin=$null;$original=@{}
try{
  Compose @('--profile','rabbitmq','--profile','rocketmq','up','-d','--wait','rabbitmq-broker','rocketmq-broker')
  $env:SCHEDULING_RABBITMQ_ENABLED='true';$env:SCHEDULING_ROCKETMQ_ENABLED='true';$env:SCHEDULING_RABBITMQ_PUBLISH_FIXED_DELAY='1s';$env:SCHEDULING_ROCKETMQ_PUBLISH_FIXED_DELAY='1s';Compose @('--profile','rabbitmq','--profile','rocketmq','up','-d','--no-deps','--force-recreate','commerce-service','commerce-portal-angular');Wait-Web
  $admin=Session 'admin@example.com';$policies=Invoke-RestMethod "$BaseUrl/api/admin/scheduling/policies" -WebSession $admin.Session;foreach($type in @('AUTO_RECEIVE','AUTO_COMPLETE')){$original[$type]=@($policies.Where({$_.taskType-eq$type}))[0];if(-not$original[$type]){throw "Missing $type policy"}}
  foreach($trigger in @('RABBITMQ','ROCKETMQ')){
    Set-Policy $admin 'AUTO_RECEIVE' $trigger|Out-Null;Set-Policy $admin 'AUTO_COMPLETE' $trigger|Out-Null
    Broker $trigger stop
    $receiveOrder=New-DeliveredOrder;$receiveTask=[long](Wait-Sql "SELECT id FROM scheduled_tasks WHERE task_type='AUTO_RECEIVE' AND task_key='order:$receiveOrder'" {param($v) -not [string]::IsNullOrWhiteSpace($v)} "$trigger AUTO_RECEIVE creation");$snapshot=Sql "SELECT primary_trigger_snapshot FROM scheduled_tasks WHERE id=$receiveTask";if($snapshot-ne$trigger){throw "AUTO_RECEIVE snapshot is $snapshot, expected $trigger"};Assert-PublishFailure $receiveTask "$trigger AUTO_RECEIVE";Sql "UPDATE scheduled_tasks SET due_at=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 1 SECOND) WHERE id=$receiveTask"|Out-Null;Broker $trigger start;Verify-Task $receiveTask $trigger 'RECEIVED' $receiveOrder

    Broker $trigger stop
    $completeOrder=New-DeliveredOrder;Wait-Sql "SELECT id FROM scheduled_tasks WHERE task_type='AUTO_RECEIVE' AND task_key='order:$completeOrder'" {param($v) -not [string]::IsNullOrWhiteSpace($v)} "$trigger AUTO_RECEIVE fixture creation"|Out-Null;$customer=Session 'demo@example.com';$received=Invoke-RestMethod "$BaseUrl/api/purchase-orders/$completeOrder/receive" -Method Post -WebSession $customer.Session -Headers $customer.Headers -ContentType application/json -Body '{}';if($received.status-ne'RECEIVED'){throw 'Manual receipt fixture failed'};$receiveState=Sql "SELECT status FROM scheduled_tasks WHERE task_type='AUTO_RECEIVE' AND task_key='order:$completeOrder'";if($receiveState-ne'CANCELLED'){throw 'Manual receipt did not cancel AUTO_RECEIVE'};$completeTask=[long](Sql "SELECT id FROM scheduled_tasks WHERE task_type='AUTO_COMPLETE' AND task_key='order:$completeOrder'");$snapshot=Sql "SELECT primary_trigger_snapshot FROM scheduled_tasks WHERE id=$completeTask";if($snapshot-ne$trigger){throw "AUTO_COMPLETE snapshot is $snapshot, expected $trigger"};Assert-PublishFailure $completeTask "$trigger AUTO_COMPLETE";Sql "UPDATE scheduled_tasks SET due_at=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 1 SECOND) WHERE id=$completeTask"|Out-Null;Broker $trigger start;Verify-Task $completeTask $trigger 'COMPLETED' $completeOrder
  }
  Write-Host 'AUTO_RECEIVE/AUTO_COMPLETE MQ failure verification passed for RabbitMQ and RocketMQ: publish failure, broker recovery, snapshot execution and single side effect.' -ForegroundColor Green
}finally{
  try{if($admin){foreach($type in @('AUTO_RECEIVE','AUTO_COMPLETE')){if($original[$type].source-eq'DATABASE_OVERRIDE'){Set-Policy $admin $type '' $original[$type]|Out-Null}else{Invoke-RestMethod "$BaseUrl/api/admin/scheduling/policies/$type" -Method Delete -WebSession $admin.Session -Headers $admin.Headers|Out-Null}}}}catch{Write-Warning "Policy restore failed: $_"}
  foreach($n in $envNames){if($null-eq$saved[$n]){Remove-Item "Env:$n" -ErrorAction SilentlyContinue}else{Set-Item "Env:$n" $saved[$n]}}
  try{Compose @('--profile','rabbitmq','--profile','rocketmq','up','-d','--wait','rabbitmq-broker','rocketmq-broker')}catch{Write-Warning "Broker restore failed: $_"}
  try{Compose @('up','-d','--no-deps','--force-recreate','commerce-service','commerce-portal-angular')}catch{Write-Warning "Backend restore failed: $_"}
}
